    본문: "하나님의 뜻으로 말미암아 그리스도 예수의 사도 된 바울은 에베소에 있는 성도들과 그리스도 예수 안의 신실한 자들에게",
    표1_원어분석: [
        {"원어":"ἀπόστολος (아포스톨로스)", "의미_문법":"사도 - 명사 남성 단수 주격. 보냄을 받은 자라는 뜻", "설교포인트":"바울의 사도권은 인간의 임명이 아닌 하나님의 뜻에서 비롯되었음을 선언한다"},
        {"원어":"θελήματος (델레마토스)", "의미_문법":"뜻/의지 - 명사 중성 단수 속격. 하나님의 주권적 의지", "설교포인트":"사역의 근거는 인간의 열심이 아니라 하나님의 뜻이어야 한다"},
        {"원어":"ἁγίοις (하기오이스)", "의미_문법":"성도들 - 형용사(명사적) 남성 복수 여격. 거룩하게 구별된 자들", "설교포인트":"성도는 도덕적 완전함이 아니라 하나님께 구별된 신분이다"},
        {"원어":"πιστοῖς (피스토이스)", "의미_문법":"신실한 자들 - 형용사 남성 복수 여격. 믿음 있고 신뢰할 수 있는", "설교포인트":"성도는 거룩한 신분과 신실한 삶 두 특성을 함께 가져야 한다"}
    ],
    표2_역사적배경: [
        {"항목":"에베소의 지리적 중요성", "내용":"에베소는 소아시아의 수도이자 로마 제국 3대 도시 중 하나였다. 아르테미스 신전이 있는 종교적 중심지였으며 바울이 약 3년간 집중 사역한 곳이다", "목회적활용":"복음은 세상의 중심부에서 전략적으로 전파되어야 한다. 지역 문화를 이해한 복음 사역이 필요하다"},
        {"항목":"바울의 사도적 권위 주장", "내용":"갈라디아서와 동일하게 바울은 자신의 사도권이 하나님의 뜻에서 비롯됨을 강조한다. 거짓 교사들의 도전에 대한 방어이기도 했다", "목회적활용":"목회자는 자신의 부르심을 인간의 기대가 아닌 하나님의 뜻에 근거해야 한다"},
        {"항목":"에베소 교회의 다양성", "내용":"에베소 교회는 유대인과 이방인이 함께하는 다민족 공동체였다. 이 다양성 속의 통일이 에베소서의 핵심 주제 중 하나이다", "목회적활용":"다양성 속의 일치는 초대 교회부터의 목회적 과제로 오늘날 다문화 사회에서도 동일하게 적용된다"}
    ],
