        {"구분":"성막의 하나님 임재", "내용":"구약 성막과 성전에 하나님의 영광이 충만함 (출 40:34-35, 왕상 8:10-11)은 하나님의 임재와 충만함의 예표", "그리스도연결":"교회가 그리스도의 충만함이 거하는 곳이 됨 — 성전보다 위대한 교회 (요 2:21, 엡 2:21-22)"},
        {"구분":"솔로몬 성전의 충만", "내용":"솔로몬 성전에 하나님의 영광이 가득 차서 제사장들이 서 있지 못했음 (왕상 8:10-11)", "그리스도연결":"신약 교회에 성령으로 그리스도의 충만함이 임하심 (엡 5:18)"},
        {"구분":"이스라엘의 사명", "내용":"이스라엘은 열방에 하나님의 영광을 드러내야 할 사명을 가졌음 (사 43:12)", "그리스도연결":"교회는 세상에 그리스도의 충만함을 나타내는 사명을 가짐 (엡 3:10)"}
